  /// by passing `null`.
  Lali copyWith({bool? lulu, FixedPoint? loli}) {
    return Lali(lulu: lulu ?? this.lulu, loli: loli ?? this.loli);
  }

  @override
  bool operator ==(Object other) =>
      other is Lali &&
      lulu == other.lulu &&
      loliFpType.sameEncoding(loli, other.loli);

  @override
  int get hashCode => Object.hashAll([lulu, loliFpType.encodeRaw(loli)]);

  @override
  String toString() => 'Lali(lulu: $lulu, loli: $loli)';
}
